// caveman:native-opencode — GENERATED by `caveman enable opencode`.
// OpenCode V2 plugin: session prompt/context hooks, tool hooks, and event stream.
// Local edits (2026-11-13): async child processes so hooks never block the
// OpenCode server, and no per-tool PreToolUse/PostToolUse native-hook calls.
// Original kept at ../plugins-disabled/caveman-native.js.orig.
// `caveman enable opencode` regenerates this file and drops these edits.
import { execFile } from "node:child_process";
import { createHash } from "node:crypto";

const command = "/opt/homebrew/bin/caveman";
const prefix = [];
const contexts = new Map();
const pending = new Map();

function run(args, input, timeout, maxBuffer = 1024 * 1024) {
  return new Promise((resolve) => {
    const child = execFile(command, [...prefix, ...args], { encoding: "utf8", timeout, maxBuffer }, (error, stdout) => {
      resolve(error ? undefined : stdout);
    });
    child.stdin?.on("error", () => {});
    child.stdin?.end(input);
  });
}

async function call(event, payload = {}) {
  const raw = await run(["native-hook", "opencode", event], JSON.stringify({ event_name: event, ...payload }), 2000, 2 * 1024 * 1024);
  if (!raw?.trim()) return undefined;
  try {
    const value = JSON.parse(raw);
    return value && typeof value === "object" ? value : undefined;
  } catch { return undefined; }
}

function digest(value) {
  try {
    const raw = JSON.stringify(value);
    return { bytes: Buffer.byteLength(raw), sha256: "sha256:" + createHash("sha256").update(raw).digest("hex") };
  } catch { return undefined; }
}

function taskType(value) {
  let text;
  try { text = JSON.stringify(value).toLowerCase(); } catch { return "general"; }
  const has = (...terms) => terms.some((term) => text.includes(term));
  if (has("migration", "migrate", "schema change", "backfill", "rollback")) return "migration";
  if (has("bug", "fix", "broken", "regression", "crash", "error", "incorrect")) return "bugfix";
  if (has("investigate", "diagnose", "root cause", "why does", "trace")) return "investigation";
  if (has("refactor", "restructure", "reorganize", "cleanup")) return "refactor";
  if (has("review", "audit", "critique", "assess")) return "review";
  if (has("verify", "verification", "prove", "validate", "check that")) return "verification";
  if (has("build", "implement", "add", "create", "ship", "feature")) return "feature";
  return "general";
}

function taskTerms(value) {
  let text;
  try { text = JSON.stringify(value); } catch { return []; }
  const stop = new Set(["about", "after", "agent", "before", "build", "change", "code", "create", "from", "have", "help", "implement", "into", "make", "please", "project", "repository", "should", "spec", "task", "that", "then", "there", "these", "they", "this", "through", "user", "want", "what", "when", "where", "which", "with", "would", "your"]);
  const out = [];
  const seen = new Set();
  for (const raw of text.match(/[A-Za-z][A-Za-z0-9_./-]{2,63}/g) ?? []) {
    const term = raw.toLowerCase().replace(/^[-./]+|[-./]+$/g, "");
    if (!term || term.includes("..") || stop.has(term) || seen.has(term) || /^(?:sk|pk|rk|ghp|github_pat|xox[baprs]|akia)[-_]/i.test(term) || /^[a-z0-9_-]{40,}$/i.test(term)) continue;
    seen.add(term);
    out.push(term);
    if (out.length === 12) break;
  }
  return out;
}

function taskContinuation(value) {
  const visit = (item) => {
    if (typeof item === "string") return item;
    if (Array.isArray(item)) return item.map(visit).filter(Boolean).join(" ");
    if (!item || typeof item !== "object") return "";
    return visit(item.text ?? item.content ?? item.message ?? "");
  };
  const prompt = visit(value).trim().toLowerCase();
  if (!prompt || prompt.length > 160 || prompt.split(/s+/).length > 14) return false;
  return /^(?:pleases+)?(?:continue|go ahead|keep going|proceed|do (?:it|that)|fix (?:it|that)|retry|try again|explain (?:it|that)|what do you mean|yes|yep|yeah|why??|how??)[.!?s]*$/.test(prompt);
}

async function sessionContext(sessionID) {
  if (!sessionID) return undefined;
  if (!contexts.has(sessionID)) {
    const request = call("SessionStart", { session_id: sessionID, surface: "cli" }).then((out) => {
      const context = out?.hookSpecificOutput?.additionalContext;
      if (typeof context === "string" && context) return context;
      contexts.delete(sessionID);
      return undefined;
    });
    contexts.set(sessionID, request);
  }
  return contexts.get(sessionID);
}

export const CavemanNative = {
  id: "caveman-native",
  async setup(ctx) {
    const controller = new AbortController();
    void (async () => {
      try {
        for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
          const props = event?.data ?? event?.properties ?? {};
          const sessionID = props.sessionID ?? props.info?.id ?? props.id;
          if (event.type === "session.created") void sessionContext(sessionID);
          if (["session.idle", "session.execution.succeeded", "session.execution.failed", "session.execution.interrupted"].includes(event.type)) {
            void call("Stop", { session_id: sessionID });
          }
          if (event.type === "session.compacted") {
            void call("PostCompact", { session_id: sessionID }).then((out) => {
              const context = out?.hookSpecificOutput?.additionalContext;
              if (typeof context === "string" && context) contexts.set(sessionID, Promise.resolve(context));
            });
          }
          if (event.type === "session.deleted") {
            void call("SessionEnd", { session_id: sessionID });
            contexts.delete(sessionID);
            pending.delete(sessionID);
          }
        }
      } catch (error) {
        if (!controller.signal.aborted) console.warn("[caveman-native] event subscription failed:", error.message);
      }
    })();

    await ctx.session.hook("prompt", async (event) => {
      const prompt = event.prompt?.text ?? "";
      const decision = await call("UserPromptSubmit", {
        session_id: event.sessionID,
        model: event.model?.id,
        provider: event.model?.providerID,
        prompt: digest(prompt),
        task_type: taskType(prompt),
        task_terms: taskTerms(prompt),
        task_continuation: taskContinuation(prompt),
      });
      const dynamic = decision?.hookSpecificOutput?.additionalContext;
      if (typeof dynamic === "string" && dynamic) pending.set(event.sessionID, dynamic);
    });

    await ctx.session.hook("context", async (event) => {
      const stable = await sessionContext(event.sessionID);
      if (stable) event.system.push({ type: "text", text: stable });
      const hint = pending.get(event.sessionID);
      if (hint) {
        event.system.push({ type: "text", text: hint });
        pending.delete(event.sessionID);
      }
    });

    await ctx.tool.hook("execute.before", async (event) => {
      if ((event.tool !== "bash" && event.tool !== "shell") || typeof event.input?.command !== "string") return;
      const raw = await run(["shrink-hook"], JSON.stringify({ tool_name: "Bash", tool_input: { command: event.input.command } }), 750);
      try {
        const rewritten = JSON.parse(raw ?? "")?.hookSpecificOutput?.updatedInput?.command;
        if (typeof rewritten === "string" && rewritten) event.input.command = rewritten;
      } catch {}
    });

    await ctx.session.hook("compaction", async (event) => {
      void call("PreCompact", { session_id: event.sessionID });
      const stable = await sessionContext(event.sessionID);
      if (stable) event.system.push({ type: "text", text: stable });
    });

    return () => {
      controller.abort();
      for (const sessionID of contexts.keys()) void call("SessionEnd", { session_id: sessionID });
      contexts.clear();
      pending.clear();
    };
  },
};

export default CavemanNative;
